function tokenize(str){
  var raw = String(str).replace(/[_\-\s]+/g, ' ').replace(/([a-z0-9])([A-Z])/g, '$1 $2');
  return raw.trim().split(/\s+/).filter(Boolean);
}
function toCamel(s){ var w=tokenize(s); return w.map(function(x,i){ return i===0? x.toLowerCase() : x.charAt(0).toUpperCase()+x.slice(1).toLowerCase(); }).join(''); }
function toPascal(s){ return toCamel(s).charAt(0).toUpperCase()+toCamel(s).slice(1); }
function toSnake(s){ return tokenize(s).map(function(x){return x.toLowerCase();}).join('_'); }
function toKebab(s){ return tokenize(s).map(function(x){return x.toLowerCase();}).join('-'); }
function toTitle(s){ return tokenize(s).map(function(x){return x.charAt(0).toUpperCase()+x.slice(1).toLowerCase();}).join(' '); }
function toUpper(s){ return String(s).toUpperCase(); }
function toLower(s){ return String(s).toLowerCase(); }
function toSentence(s){ var t=tokenize(s).join(' ').toLowerCase(); return t.charAt(0).toUpperCase()+t.slice(1); }
function toToggle(s){ return String(s).replace(/[a-zA-Z]/g, function(c){ return /[a-z]/.test(c)? c.toUpperCase(): c.toLowerCase(); }); }
function toAlternating(s){ var up=false; return String(s).replace(/[a-zA-Z]/g, function(c){ var res = up? c.toUpperCase(): c.toLowerCase(); up=!up; return res; }); }
var EXPORTS = { tokenize:tokenize, toCamel:toCamel, toPascal:toPascal, toSnake:toSnake, toKebab:toKebab, toTitle:toTitle, toUpper:toUpper, toLower:toLower, toSentence:toSentence, toToggle:toToggle, toAlternating:toAlternating };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CaseConvertForgePure = EXPORTS; }
